import fs from "node:fs";
import path from "node:path";

const root = process.cwd();
const output = path.join(root, "public");
let copied = 0;

// public is exclusively generated by this script. Check the exact target before
// clearing it, so assets removed from source cannot survive a later build.
if (path.dirname(output) !== root || path.basename(output) !== "public")
  throw new Error("Unsafe generated asset path");
if (fs.existsSync(output)) {
  if (
    fs.lstatSync(output).isSymbolicLink() ||
    fs.realpathSync(output) !== path.join(fs.realpathSync(root), "public")
  )
    throw new Error("Refusing to clear a linked asset directory");
  fs.rmSync(output, { recursive: true });
}

function copyAssets(source, destination) {
  if (!fs.existsSync(source)) return;
  fs.mkdirSync(destination, { recursive: true });
  for (const item of fs.readdirSync(source, { withFileTypes: true })) {
    const from = path.join(source, item.name);
    const to = path.join(destination, item.name);
    if (item.isDirectory()) copyAssets(from, to);
    else if (item.isFile() && !/\.mdx?$/i.test(item.name)) {
      fs.copyFileSync(from, to);
      copied += 1;
    }
  }
}

// Hugo copied /static to the root and page-bundle files beside their pages.
// Retaining those URLs preserves figures and linked PDF reports in old articles.
copyAssets(path.join(root, "static"), output);
for (const section of ["projects", "studies"]) {
  copyAssets(path.join(root, "content", section), path.join(output, section));
}
fs.writeFileSync(path.join(output, ".nojekyll"), "");
console.log(`Preserved ${copied} portfolio assets at their existing URLs.`);
